<script setup lang="ts">
import { HOSPITAL_NAME, HOSPITAL_CITY } from '../domain/branding'
import { Printer, ArrowLeft, AlertCircle } from '@lucide/vue'
import { formatHours, monthDates, monthLabel, prettyDate, weekday } from '../domain/calendar'
import { clockLabel, planShifts, shiftHours } from '../domain/shifts'
const w = useWorkspace()
const dates = computed(() => monthDates(w.activeMonth.value))
const legend = computed(() => w.data.value && w.plan.value ? planShifts(w.data.value, w.plan.value).filter(s => new Set(Object.values(w.plan.value!.assignments).flatMap(r => Object.values(r))).has(s.code)) : [])
const unresolved = computed(() => w.issues.value.filter(i => i.severity === 'error'))
const showWarnings = ref(true)
const total = computed(() => w.summaries.value.reduce((n, r) => n + r.knownHours, 0))
useHead({ title: computed(() => `Jadwal Dokter ${monthLabel(w.activeMonth.value)} · RSUD LEWOLEBA`) })
function print() { window.print() }
</script>
<template>
  <div class="screen-only"><PageHeading title="Cetak jadwal" eyebrow="Dokumen bulanan"><MonthSelect/><button class="btn btn-primary" :disabled="!w.plan.value" @click="print"><Printer :size="16"/>Cetak / Simpan PDF</button></PageHeading><div v-if="w.isAdmin.value" class="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-brand-100 bg-brand-50 px-5 py-3"><NuxtLink to="/pengaturan" class="text-xs font-semibold text-brand-700">Atur nama & NIP</NuxtLink></div><label v-if="unresolved.length" class="mb-4 flex items-center gap-2 text-xs text-slate-600"><input v-model="showWarnings" type="checkbox"/>Sertakan catatan {{ unresolved.length }} benturan dinas pada dokumen</label></div>
  <div v-if="w.plan.value && w.data.value" class="print-wrap scrollbar-thin panel overflow-x-auto p-5"><article class="print-document mx-auto min-w-[1000px] max-w-[1300px] p-5 text-xs"><header class="mb-5 text-center"><p class="text-xs font-medium tracking-[0.1em] text-slate-600">{{ HOSPITAL_NAME }}</p><h1 class="mt-2 text-xl font-bold tracking-wide">JADWAL DOKTER JAGA</h1><p class="mt-1 text-xs font-medium">BULAN {{ monthLabel(w.activeMonth.value).toUpperCase() }}</p><p class="mt-1 text-[9px] text-slate-600">{{ w.plan.value.locked ? 'Jadwal terkunci' : 'Draf jadwal' }} · waktu setempat {{ w.data.value.settings.timezone === 'Asia/Makassar' ? 'WITA' : w.data.value.settings.timezone === 'Asia/Jayapura' ? 'WIT' : 'WIB' }}</p></header><table><thead><tr class="bg-brand-50"><th class="print-number">No.</th><th class="print-name">Dokter</th><th v-for="(date, i) in dates" :key="date"><p class="text-[8px] font-normal">{{ weekday(date) }}</p><p class="mt-0.5">{{ i + 1 }}</p></th><th class="print-total">Jam</th></tr></thead><tbody><tr v-for="(r, i) in w.summaries.value" :key="r.doctor.id"><td>{{ i + 1 }}</td><td class="print-name font-medium">{{ r.doctor.name }}</td><td v-for="date in dates" :key="date" :class="['L', 'C', 'BM'].includes(w.plan.value.assignments[r.doctor.id]?.[date] ?? '') ? 'bg-slate-50 text-slate-600' : ''">{{ w.plan.value.assignments[r.doctor.id]?.[date] || '—' }}</td><td class="font-semibold">{{ formatHours(r.totalHours) }}</td></tr><tr><td :colspan="dates.length + 2" class="text-right! pr-3! font-semibold">Total jam terjadwal</td><td class="font-bold">{{ formatHours(total) }}</td></tr></tbody></table><div class="print-legend mt-4 grid grid-cols-3 gap-x-6 gap-y-1.5"><p v-for="s in legend" :key="s.code"><strong>{{ s.code }}</strong> · {{ clockLabel(s) }} · {{ shiftHours(s) }} jam</p></div><p class="mt-2 text-[8px] text-slate-600">+1 = hari berikutnya.</p><p v-if="w.summaries.value.some(r => r.emptyDays)" class="mt-2 text-[8px] text-amber-700">Jadwal belum lengkap.</p><p v-if="showWarnings && unresolved.length" class="mt-2 rounded border border-amber-200 bg-amber-50 px-3 py-2 text-[8px] text-amber-800">Catatan pemeriksaan: {{ unresolved.length }} benturan dinas, termasuk {{ unresolved.filter(i => i.historical).length }} catatan riwayat.</p><div class="signature-block mt-6 grid grid-cols-2 gap-20 px-8 text-center text-xs"><div><p>Mengetahui,</p><p class="mt-1 font-semibold">DIREKTUR {{ HOSPITAL_NAME }}</p><div class="signature-space h-16"/><p class="font-semibold underline underline-offset-2">{{ w.data.value.settings.director || '' }}</p><p class="mt-1">NIP: {{ w.data.value.settings.directorNip || '' }}</p></div><div><p>{{ !w.data.value.settings.city || w.data.value.settings.city === 'Kota Anda' ? HOSPITAL_CITY : w.data.value.settings.city }}, {{ w.data.value.settings.signedDate ? prettyDate(w.data.value.settings.signedDate) : '' }}</p><p class="mt-1 font-semibold">KEPALA SEKSI PELAYANAN MEDIK</p><div class="signature-space h-16"/><p class="font-semibold underline underline-offset-2">{{ w.data.value.settings.sectionHead || '' }}</p><p class="mt-1">NIP: {{ w.data.value.settings.sectionHeadNip || '' }}</p></div></div></article></div>
  <div v-else class="panel p-8 text-sm text-slate-600">Belum ada jadwal yang dapat dicetak.</div>
</template>
